func minWindow(s string, t string) string {
    if len(s) < len(t) {
        return ""
    }
    need := make(map[byte]int)
    for i := 0; i < len(t); i++ {
        need[t[i]]++
    }
    window := make(map[byte]int)
    have, total := 0, len(need) // total = 需要满足的字符种类数
    resL, resLen := 0, len(s)+1

    left := 0
    for right := 0; right < len(s); right++ {
        c := s[right]
        window[c]++
        if window[c] == need[c] {
            have++
        }
        for have == total {
            if right-left+1 < resLen {
                resL, resLen = left, right-left+1
            }
            d := s[left]
            window[d]--
            if window[d] < need[d] {
                have--
            }
            left++
        }
    }
    if resLen > len(s) {
        return ""
    }
    return s[resL : resL+resLen]
}
